import fs from 'fs';

const GIELDA_CATEGORY = 'Giełda z sesji 2023/2024 (semestr letni)';

const items = [
  { targetCategory: 'Skrypt — Ból', q: 'Jaka endogenna substancja hamuje przewodnictwo bólowe?', o: ['endorfina', 'morfina', 'bradykinina', 'substancja P', 'prostaglandyna E2'], a: 0, rationale: "Poprawnie: endorfiny są endogennymi peptydami opioidowymi, wiążącymi się z receptorami opioidowymi i hamującymi przewodnictwo bólowe na poziomie rdzenia kręgowego i mózgu. Morfina jest egzogennym (zewnętrznym) opioidem, lekiem, nie substancją endogenną wytwarzaną przez organizm. Bradykinina jest mediatorem NASILAJĄCYM ból, działającym przeciwnie do endorfin. Substancja P jest neuroprzekaźnikiem przekazującym (nasilającym), nie hamującym sygnał bólowy w rdzeniu kręgowym. Prostaglandyna E2 uwrażliwia nocyceptory, nasilając odczuwanie bólu, działając przeciwnie do endorfin." },
  { targetCategory: 'Podręcznik patofizjologii — Skazy krwotoczne', q: 'U pacjenta stwierdzono liczne drobne, podskórne wybroczyny (petechiae). Co należy zbadać w pierwszej kolejności?', o: ['liczbę płytek krwi', 'stężenie czynnika VIII', 'czas protrombinowy (PT) jako pierwszy wybór', 'stężenie fibrynogenu jako pierwszy wybór', 'czas częściowej tromboplastyny po aktywacji (APTT) jako pierwszy wybór'], a: 0, rationale: "Poprawnie: drobne, punktowe wybroczyny (petechiae) są klasycznym objawem skazy płytkowej, więc pierwszym, kluczowym badaniem jest liczba płytek krwi. Stężenie czynnika VIII jest badane przy podejrzeniu hemofilii A, która daje raczej głębokie krwiaki i krwawienia do stawów, nie drobne petechiae. PT jest bardziej użyteczny w diagnostyce skaz osoczowych (droga zewnątrzpochodna), dających inny obraz kliniczny niż drobne petechiae typowe dla skazy płytkowej. Fibrynogen jest istotny w diagnostyce zaburzeń krzepnięcia osoczowego lub DIC, nie jest pierwszym wyborem przy obrazie klinicznym sugerującym skazę płytkową. APTT ocenia drogę wewnątrzpochodną krzepnięcia osoczowego, mniej swoisty dla obrazu drobnych petechiae typowych dla trombocytopenii." },
  { targetCategory: 'Prezentacje — Fizjologia krwi', q: 'Co zmniejsza powinowactwo hemoglobiny do tlenu, pozwalając na jego odłączenie w tkankach?', o: ['wzrost prężności CO2 w osoczu (efekt Bohra)', 'wzrost prężności O2 w osoczu', 'spadek temperatury', 'spadek stężenia 2,3-DPG', 'wzrost pH (zasadowica)'], a: 0, rationale: "Poprawnie: wzrost prężności CO2 (i wynikający z niego spadek pH) w aktywnych metabolicznie tkankach zmniejsza powinowactwo hemoglobiny do tlenu (efekt Bohra), ułatwiając jego uwalnianie tam, gdzie jest najbardziej potrzebny. Wzrost prężności O2 zwiększałby, nie zmniejszał powinowactwo — to warunek panujący w płucach, sprzyjający wysyceniu hemoglobiny tlenem, nie jego uwalnianiu. Spadek temperatury ZWIĘKSZA powinowactwo hemoglobiny do tlenu (przesunięcie krzywej w lewo), utrudniając jego uwalnianie, nie ułatwiając. Spadek 2,3-DPG ZWIĘKSZA powinowactwo hemoglobiny do tlenu, działając przeciwnie do potrzeby jego uwalniania w tkankach. Wzrost pH (zasadowica) ZWIĘKSZA powinowactwo hemoglobiny do tlenu, utrudniając jego oddawanie tkankom." },
  { targetCategory: 'Wykład 11 — Zaburzenia rytmu serca (arytmie)', q: 'Jak wygląda pobudzenie ektopowe pochodzące z komory w zapisie EKG?', o: ['szerokie, zniekształcone zespoły QRS, niepoprzedzone załamkiem P', 'wąskie, prawidłowe zespoły QRS poprzedzone załamkiem P', 'wyłącznie zmiana załamka P bez zmiany QRS', 'brak jakichkolwiek zmian w zapisie EKG', 'wydłużenie odstępu PQ bez zmiany kształtu QRS'], a: 0, rationale: "Poprawnie: pobudzenie ektopowe z komory powstaje poza prawidłowym układem przewodzącym, dając szerokie, zniekształcone zespoły QRS, zwykle niepoprzedzone (lub z dysocjowanym) załamkiem P. Wąskie, prawidłowe QRS poprzedzone P jest typowe dla prawidłowego rytmu zatokowego lub pobudzeń nadkomorowych, nie komorowych. Pobudzenie komorowe wpływa przede wszystkim na kształt zespołu QRS (jego poszerzenie i zniekształcenie), nie ogranicza się do zmiany załamka P. Pobudzenie ektopowe komorowe daje wyraźne, charakterystyczne zmiany w zapisie EKG, więc brak zmian jest nieprawdziwy. Wydłużenie PQ bez zmiany QRS opisuje blok AV I stopnia, odrębne zjawisko od pobudzenia ektopowego komorowego." },
  { targetCategory: 'Wykład 11 — Zaburzenia rytmu serca (arytmie)', q: 'Jaka częstość akcji komór może towarzyszyć migotaniu przedsionków?', o: ['tachykardia, normokardia lub bradykardia (zależnie od przewodzenia przez węzeł AV)', 'zawsze niemiarowa bradykardia', 'zawsze miarowa tachykardia', 'wyłącznie normokardia', 'zawsze zatrzymanie akcji komór'], a: 0, rationale: "Poprawnie: częstość odpowiedzi komorowej w migotaniu przedsionków zależy od przewodzenia przez węzeł AV i może obejmować tachykardię, normokardię lub bradykardię, przy zawsze zachowanej niemiarowości rytmu komór. Twierdzenie o zawsze niemiarowej bradykardii pomija możliwość wystąpienia tachykardii lub normokardii przy migotaniu przedsionków, zależnie od przewodzenia AV. Migotanie przedsionków z definicji daje NIEMIAROWY rytm komór — 'miarowa tachykardia' jest sprzeczna z samą definicją tej arytmii. Częstość komór w migotaniu przedsionków jest zmienna, nie ograniczona wyłącznie do normokardii. Migotanie przedsionków nie powoduje zatrzymania akcji komór — komory nadal biją, choć niemiarowo, z różną częstością." },
  { targetCategory: 'Podręcznik patofizjologii — Przysadka i tarczyca', q: 'Jaki neuroprzekaźnik jest wydzielany do krążenia wrotnego przysadki i hamuje wydzielanie prolaktyny?', o: ['dopamina', 'grelina', 'acetylocholina', 'noradrenalina', 'serotonina'], a: 0, rationale: "Poprawnie: dopamina, wydzielana przez neurony podwzgórza do krążenia wrotnego podwzgórzowo-przysadkowego, jest głównym czynnikiem hamującym wydzielanie prolaktyny przez laktotropy przedniego płata przysadki. Grelina reguluje głównie łaknienie i wydzielanie GH, niebędąca głównym inhibitorem prolaktyny. Acetylocholina nie jest głównym, klasycznym neuroprzekaźnikiem regulującym wydzielanie prolaktyny w tym mechanizmie. Noradrenalina nie jest głównym czynnikiem hamującym prolaktynę — tę rolę pełni dopamina. Serotonina raczej NASILA wydzielanie prolaktyny (stąd hiperprolaktynemia przy niektórych lekach przeciwdepresyjnych zwiększających serotoninę), działając przeciwnie do dopaminy." },
  { targetCategory: 'Podręcznik patofizjologii — Przysadka i tarczyca', q: 'U pacjenta stwierdzono nadmiar TSH i niedobór T4. Jakie to zaburzenie?', o: ['pierwotna niedoczynność tarczycy', 'wole obojętne', 'pierwotna nadczynność tarczycy', 'wtórna nadczynność tarczycy', 'wtórna niedoczynność tarczycy'], a: 0, rationale: "Poprawnie: wysoki TSH (kompensacyjna odpowiedź przysadki) przy niskim T4 jest klasycznym obrazem pierwotnej niedoczynności tarczycy — problem leży w samym gruczole tarczycowym. Wole obojętne cechuje się prawidłową czynnością hormonalną (eutyreozą) mimo powiększenia gruczołu, sprzeczne z opisanym zaburzeniem hormonalnym. Pierwotna nadczynność tarczycy dałaby wysokie T4 przy niskim (zahamowanym) TSH — odwrotny wzorzec do opisanego. Wtórna nadczynność dałaby podwyższone oba hormony, sprzeczne z niskim T4 w pytaniu. Wtórna niedoczynność dałaby niskie oba hormony (TSH i T4), sprzeczne z wysokim TSH opisanym w pytaniu." },
  { targetCategory: 'Wykład 11 — Zaburzenia rytmu serca (arytmie)', q: 'Co jest charakterystyczne dla bloku przedsionkowo-komorowego (AV) typu I?', o: ['wydłużenie przewodzenia AV (dłuższy odstęp PQ) przy zachowanym przewodzeniu każdego pobudzenia', 'całkowity brak przewodzenia AV', 'stopniowe wydłużanie PQ do wypadnięcia zespołu QRS', 'skrócenie odstępu PQ', 'nagłe, nieprzewidywalne wypadnięcie zespołu QRS przy stałym PQ'], a: 0, rationale: "Poprawnie: blok AV I stopnia cechuje się stałym wydłużeniem odstępu PQ powyżej 200 ms, przy zachowanym przewodzeniu KAŻDEGO pobudzenia przedsionkowego do komór (bez wypadania QRS). Całkowity brak przewodzenia AV opisuje blok III stopnia (całkowity), znacznie poważniejsze zaburzenie niż blok I stopnia. Stopniowe wydłużanie PQ do wypadnięcia QRS opisuje blok AV II stopnia typu Mobitz I (periodykę Wenckebacha), odrębną jednostkę od bloku I stopnia. Skrócenie PQ jest typowe dla zespołu preekscytacji (WPW), przeciwne do wydłużenia charakterystycznego dla bloku I stopnia. Nagłe wypadnięcie QRS przy stałym PQ opisuje blok AV II stopnia typu Mobitz II, odrębną jednostkę od bloku I stopnia (w którym QRS nigdy nie wypada)." },
  { targetCategory: 'Podręcznik patofizjologii — Niewydolność nerek', q: 'Pacjent z niewydolnością nerek hiperwentyluje. Co jest przyczyną tej hiperwentylacji?', o: ['kwasica metaboliczna (kompensacja oddechowa)', 'zasadowica oddechowa jako przyczyna pierwotna', 'zasadowica metaboliczna', 'prawidłowa równowaga kwasowo-zasadowa', 'hiperkaliemia jako bezpośrednia przyczyna hiperwentylacji'], a: 0, rationale: "Poprawnie: niewydolność nerek prowadzi do kwasicy metabolicznej (zatrzymanie kwasów, upośledzone wydalanie H+), na którą organizm kompensacyjnie reaguje hiperwentylacją, obniżając pCO2, by częściowo znormalizować pH (oddech Kussmaula). Zasadowica oddechowa jako przyczyna pierwotna byłaby odwróceniem przyczynowo-skutkowym — to hiperwentylacja jest tu SKUTKIEM kompensacji kwasicy metabolicznej, nie jej przyczyną. Zasadowica metaboliczna dawałaby przeciwny mechanizm kompensacyjny (hipowentylację, nie hiperwentylację). Niewydolność nerek istotnie zaburza równowagę kwasowo-zasadową (kwasica), więc stwierdzenie o jej prawidłowości jest nieprawdziwe. Hiperkaliemia jest częstym towarzyszącym zaburzeniem w niewydolności nerek, ale nie jest bezpośrednim mechanizmem napędzającym hiperwentylację — tym jest kwasica metaboliczna." },
  { targetCategory: 'Podręcznik patofizjologii — Nadnercza i potas', q: 'Co powoduje niedobór 21-hydroksylazy (wrodzony przerost nadnerczy)?', o: ['przerost nadnerczy, nadmiar ACTH i nadmiar androgenów', 'zanik nadnerczy, niedobór ACTH i niedobór androgenów', 'przerost nadnerczy, niedobór ACTH przy nadmiarze androgenów', 'prawidłową wielkość nadnerczy bez zmian hormonalnych', 'przerost nadnerczy, nadmiar ACTH przy niedoborze androgenów'], a: 0, rationale: "Poprawnie: niedobór 21-hydroksylazy upośledza syntezę kortyzolu, co poprzez brak hamowania zwrotnego zwiększa wydzielanie ACTH, prowadząc do przerostu kory nadnerczy i przesunięcia steroidogenezy w kierunku nadprodukcji androgenów. Zanik nadnerczy z niedoborem ACTH i androgenów opisuje odwrotny, nieprawidłowy mechanizm tej choroby. Podwyższenie ACTH przy przeroście jest prawidłowe, ale androgeny są w tym zaburzeniu PODWYŻSZONE, nie obniżone. Zaburzenie to daje istotne, wyraźne zmiany hormonalne i strukturalne, więc stwierdzenie o prawidłowej wielkości nadnerczy bez zmian jest nieprawdziwe. ACTH jest podwyższone (prawidłowo), ale androgeny są RÓWNIEŻ podwyższone, nie obniżone — to kluczowa cecha tego zaburzenia." },
  { targetCategory: 'Podręcznik patofizjologii — Gorączka', q: 'Gorączka aseptyczna (bez udziału drobnoustrojów) może towarzyszyć czemu?', o: ['zawałowi serca (rozpad martwiczej tkanki)', 'zapaleniu wyrostka robaczkowego', 'biegunce infekcyjnej', 'zakażeniu paciorkowcowemu', 'zapaleniu płuc bakteryjnemu'], a: 0, rationale: "Poprawnie: zawał serca powoduje martwicę tkanki, a produkty rozpadu martwiczych komórek wywołują gorączkę aseptyczną (bez udziału drobnoustrojów), poprzez aktywację endogennych pirogenów. Zapalenie wyrostka robaczkowego jest zwykle związane z zakażeniem bakteryjnym, dając gorączkę septyczną, nie aseptyczną. Biegunka infekcyjna z definicji wiąże się z zakażeniem (bakteryjnym/wirusowym), dając gorączkę septyczną, nie aseptyczną. Zakażenie paciorkowcowe jest klasycznym przykładem infekcji bakteryjnej, dającej gorączkę septyczną (z udziałem drobnoustrojów), nie aseptyczną. Zapalenie płuc bakteryjne jest zakażeniem, dającym gorączkę septyczną, nie aseptyczną (bez udziału drobnoustrojów)." },
  { targetCategory: 'Podręcznik patofizjologii — Anemia i policytemia', q: 'Co jest potrzebne do syntezy DNA, a którego niedobór powoduje niedokrwistość makrocytarną?', o: ['witamina B12', 'witamina C', 'witamina K', 'witamina A', 'witamina E'], a: 0, rationale: "Poprawnie: witamina B12 jest niezbędna do syntezy DNA (jako kofaktor w metabolizmie kwasu foliowego), a jej niedobór upośledza podziały komórkowe erytroblastów, dając duże, niedojrzałe erytrocyty (niedokrwistość makrocytarna/megaloblastyczna). Witamina C jest niezbędna do syntezy kolagenu, jej niedobór powoduje skazę naczyniową (szkorbut), nie niedokrwistość makrocytarną. Witamina K jest niezbędna do syntezy niektórych czynników krzepnięcia, jej niedobór powoduje skazę krwotoczną, nie niedokrwistość makrocytarną. Witamina A jest związana z widzeniem i odpornością, jej niedobór nie powoduje klasycznie niedokrwistości makrocytarnej. Witamina E jest antyoksydantem, jej niedobór może dawać niedokrwistość hemolityczną (rzadko), nie klasyczną niedokrwistość makrocytarną z zaburzenia syntezy DNA." },
  { targetCategory: 'Podręcznik patofizjologii — Anemia i policytemia', q: 'Niedobór witaminy B12 powoduje zaburzenie syntezy czego?', o: ['DNA', 'hemu', 'globiny', 'hemoglobiny bezpośrednio, bez wpływu na DNA', 'żelaza'], a: 0, rationale: "Poprawnie: witamina B12 (jako kofaktor syntazy metioninowej) jest niezbędna do prawidłowej syntezy DNA — jej niedobór upośledza podziały komórkowe, dając megaloblastyczną przemianę szpiku. Synteza hemu nie jest bezpośrednio zależna od witaminy B12 — zależy głównie od żelaza i innych enzymów szlaku porfirynowego. Synteza globiny (białkowej części hemoglobiny) nie jest bezpośrednio zależna od witaminy B12 — jej zaburzenia (np. talasemie) mają odrębne, genetyczne podłoże. Witamina B12 nie wpływa bezpośrednio na syntezę hemoglobiny — jej głównym mechanizmem działania jest wpływ na syntezę DNA, wtórnie wpływając na dojrzewanie erytrocytów. Metabolizm żelaza nie jest bezpośrednio zależny od witaminy B12 — to odrębny szlak metaboliczny." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Gdzie znajduje się ośrodek kichania?', o: ['w bocznej części rdzenia przedłużonego', 'w korze mózgowej', 'w rdzeniu kręgowym na poziomie krzyżowym', 'w móżdżku', 'w podwzgórzu'], a: 0, rationale: "Poprawnie: ośrodek kichania znajduje się w bocznej części rdzenia przedłużonego, koordynując skomplikowaną sekwencję odruchową obejmującą mięśnie oddechowe, gardło i nos. Kora mózgowa nie jest głównym ośrodkiem koordynującym odruch kichania, choć może modulować jego świadomą percepcję. Rdzeń kręgowy na poziomie krzyżowym jest miejscem ośrodka defekacji, nie kichania — te ośrodki mają różną lokalizację. Móżdżek koordynuje płynność ruchu, nie jest głównym ośrodkiem odruchu kichania. Podwzgórze reguluje funkcje autonomiczne i hormonalne, nie jest głównym ośrodkiem koordynującym odruch kichania." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Który ośrodek jest nadrzędnym regulatorem rytmu okołodobowego (zegara biologicznego)?', o: ['jądro nadskrzyżowaniowe podwzgórza', 'jądro nadwzrokowe podwzgórza', 'jądro przykomorowe podwzgórza', 'ciało migdałowate', 'hipokamp'], a: 0, rationale: "Poprawnie: jądro nadskrzyżowaniowe (suprachiazmatyczne) podwzgórza jest głównym, nadrzędnym ośrodkiem generującym i synchronizującym rytm okołodobowy organizmu, odbierającym informację o świetle z siatkówki. Jądro nadwzrokowe produkuje wazopresynę i oksytocynę, niebędące głównym ośrodkiem regulacji rytmu dobowego. Jądro przykomorowe również produkuje hormony (wazopresynę, oksytocynę, CRH), niebędące głównym zegarem biologicznym. Ciało migdałowate odpowiada za emocje i pamięć emocjonalną, niezwiązane z generowaniem rytmu dobowego. Hipokamp odpowiada za konsolidację pamięci, niezwiązany z nadrzędną regulacją rytmu okołodobowego." },
  { targetCategory: 'Podręcznik patofizjologii — Woda i sód', q: 'Jakie jest działanie przedsionkowego peptydu natriuretycznego (ANP)?', o: ['nasila natriurezę i diurezę, rozszerza naczynia, hamuje RAA i wazopresynę', 'zatrzymuje sód i wodę, kurczy naczynia', 'pobudza układ RAA', 'nasila wydzielanie wazopresyny', 'nie ma wpływu na gospodarkę wodno-elektrolitową'], a: 0, rationale: "Poprawnie: ANP, wydzielany przez przedsionki w odpowiedzi na ich rozciągnięcie, nasila wydalanie sodu i wody (natriureza/diureza), rozszerza naczynia oraz hamuje układ RAA i wydzielanie wazopresyny, działając jako fizjologiczny antagonista tych mechanizmów zatrzymujących płyny. Zatrzymywanie sodu i wody z kurczeniem naczyń opisuje działanie PRZECIWNE do ANP, typowe dla aldosteronu/angiotensyny II. ANP HAMUJE, a nie pobudza układ RAA — to jego kluczowe, antagonistyczne działanie. ANP HAMUJE, a nie nasila wydzielanie wazopresyny — kolejny przykład jego antagonistycznego działania. ANP ma istotny, dobrze udokumentowany wpływ na gospodarkę wodno-elektrolitową, więc stwierdzenie o braku wpływu jest nieprawdziwe." },
  { targetCategory: 'Skrypt — Wywody Wody Werki', q: 'Jak brzmi definicja hormonu?', o: ['substancja organiczna wytwarzana w gruczołach lub tkankach, transportowana przez krew, regulująca procesy biochemiczne w odległych narządach', 'substancja działająca wyłącznie miejscowo, bez udziału krwiobiegu', 'wyłącznie białko wydzielane przez gruczoły dokrewne', 'enzym trawienny wydzielany do przewodu pokarmowego', 'neuroprzekaźnik działający wyłącznie w obrębie synapsy'], a: 0, rationale: "Poprawnie: hormon to substancja organiczna wytwarzana w gruczołach lub tkankach, transportowana przez krew i regulująca procesy biochemiczne/fizjologiczne w odległych narządach. Działanie wyłącznie miejscowe bez udziału krwiobiegu opisuje raczej parakrynię/autokrynię, nie klasyczne działanie hormonalne. Ograniczenie do białek pomija hormony steroidowe i pochodne aminokwasów. Definicja enzymu trawiennego dotyczy zupełnie innej klasy substancji. Neuroprzekaźnik działa lokalnie w synapsie, nie systemowo przez krew, co odróżnia go od klasycznego hormonu." },
  { targetCategory: 'Podręcznik patofizjologii — Nadkrzepliwość', q: 'Mutacja czynnika V Leiden powoduje jaki mechanizm nadkrzepliwości?', o: ['oporność czynnika V na inaktywację przez aktywowane białko C', 'nadprodukcję czynnika V bez zmiany jego wrażliwości na białko C', 'niedobór białka C', 'niedobór antytrombiny III', 'nadmierną aktywację fibrynolizy'], a: 0, rationale: "Poprawnie: mutacja czynnika V Leiden zmienia strukturę czynnika V tak, że staje się on oporny na inaktywację przez aktywowane białko C, co przedłuża jego aktywność prokoagulacyjną i sprzyja nadkrzepliwości. Nadprodukcja czynnika V bez zmiany jego wrażliwości nie oddaje istoty mutacji Leiden, która dotyczy JAKOŚCIOWEJ zmiany struktury białka, nie jego ilości. Mutacja czynnika V Leiden nie powoduje bezpośrednio niedoboru białka C — problemem jest oporność czynnika V NA działanie (prawidłowego) białka C. Mutacja ta nie dotyczy antytrombiny III, odrębnego układu antykoagulacyjnego. Mutacja czynnika V Leiden sprzyja nadkrzepliwości, nie nasilonej fibrynolizie, która działałaby przeciwzakrzepowo." },
  { targetCategory: 'Podręcznik patofizjologii — Nadkrzepliwość', q: 'Co odpowiada za tworzenie skrzeplin, zgodnie z triadą Virchowa?', o: ['zastój krwi, uszkodzenie ściany naczynia i nadkrzepliwość krwi', 'wyłącznie niedobór witaminy K', 'wyłącznie nadmierna fibrynoliza', 'wyłącznie spadek liczby erytrocytów', 'wyłącznie hipoalbuminemia'], a: 0, rationale: "Poprawnie: zgodnie z triadą Virchowa, tworzenie skrzeplin wynika z trzech czynników: zastoju krwi, uszkodzenia ściany naczynia oraz nadkrzepliwości krwi. Niedobór witaminy K powoduje raczej skazę krwotoczną (upośledzone krzepnięcie), nie sprzyja tworzeniu zakrzepów. Nadmierna fibrynoliza rozkładałaby, a nie tworzyła zakrzepy — to mechanizm przeciwny. Spadek liczby erytrocytów (anemia) nie jest głównym, klasycznym mechanizmem tworzenia zakrzepów wewnątrznaczyniowych. Hipoalbuminemia może wtórnie sprzyjać nadkrzepliwości, ale nie jest to jedyny ani główny, klasyczny mechanizm triady Virchowa." },
  { targetCategory: 'Podręcznik patofizjologii — Równowaga kwasowo-zasadowa (RKZ)', q: 'Jak wygląda oddech Kussmaula i przy jakim zaburzeniu występuje?', o: ['głęboki, przyspieszony oddech, występujący przy kwasicy metabolicznej', 'płytki, wolny oddech, występujący przy zasadowicy metabolicznej', 'oddech okresowy (naprzemienna hiper- i hipowentylacja), przy niewydolności serca', 'całkowite bezdechy, przy zatruciu opiatami', 'przyspieszony, płytki oddech, przy zasadowicy oddechowej'], a: 0, rationale: "Poprawnie: oddech Kussmaula (głęboki, przyspieszony, regularny) jest kompensacyjną odpowiedzią na kwasicę metaboliczną (np. ketonową), mającą na celu obniżenie pCO2 przez hiperwentylację. Płytki, wolny oddech przy zasadowicy metabolicznej opisuje odwrotny mechanizm — kompensacja zasadowicy metabolicznej wymaga hipowentylacji (płytszy, wolniejszy oddech), co jest inne niż oddech Kussmaula. Oddech okresowy (Cheyne'a-Stokesa) jest odrębnym wzorcem, typowym dla niewydolności serca lub uszkodzeń OUN, różniącym się od regularnego, głębokiego oddechu Kussmaula. Bezdechy przy zatruciu opiatami opisują hipowentylację/depresję oddechową, przeciwny wzorzec do hiperwentylacyjnego oddechu Kussmaula. Zasadowica oddechowa wynika z pierwotnej hiperwentylacji, ale oddech Kussmaula jest specyficznie związany z kompensacją kwasicy METABOLICZNEJ, nie z pierwotnym zaburzeniem oddechowym." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Która struktura mózgu ulega najczęściej uszkodzeniu w udarze niedokrwiennym?', o: ['obszar unaczyniony przez tętnicę środkową mózgu', 'móżdżek', 'rdzeń kręgowy', 'nerw wzrokowy', 'przysadka mózgowa'], a: 0, rationale: "Poprawnie: tętnica środkowa mózgu jest najczęściej zajmowanym naczyniem w udarach niedokrwiennych, unaczyniając rozległy obszar kory mózgowej i struktur podkorowych. Móżdżek jest rzadziej zajmowany przez udary niż obszar unaczyniony przez tętnicę środkową mózgu. Rdzeń kręgowy jest rzadko miejscem udaru niedokrwiennego w porównaniu z mózgowiem, mając odrębne unaczynienie. Nerw wzrokowy nie jest typowym miejscem udaru niedokrwiennego mózgu w klasycznym rozumieniu tego terminu. Przysadka mózgowa rzadko jest głównym miejscem klasycznego udaru niedokrwiennego mózgu, mając odrębne, specyficzne unaczynienie." },
  { targetCategory: 'Skrypt — Fizjologia układu krążenia', q: 'W echokardiografii (ECHO) serca, który parametr świadczy najlepiej o wydolności (funkcji skurczowej) serca?', o: ['frakcja wyrzutowa (EF)', 'objętość końcoworozkurczowa (EDV) w izolacji', 'grubość ściany komory w izolacji', 'średnica jamy przedsionka w izolacji', 'prędkość przepływu przez zastawkę mitralną w izolacji'], a: 0, rationale: "Poprawnie: frakcja wyrzutowa (EF), mierzona echokardiograficznie, jest kluczowym, standardowym parametrem oceny funkcji skurczowej (wydolności) lewej komory serca. Sama objętość końcoworozkurczowa bez odniesienia do objętości wyrzutowej nie oddaje bezpośrednio funkcji skurczowej serca. Grubość ściany komory w izolacji odzwierciedla przerost, nie bezpośrednio funkcję skurczową/wydolność serca. Średnica jamy przedsionka w izolacji jest istotna w innych kontekstach (np. ocena ryzyka migotania przedsionków), nie jest głównym parametrem wydolności skurczowej komory. Prędkość przepływu przez zastawkę mitralną w izolacji jest bardziej związana z oceną funkcji rozkurczowej, nie jest głównym, kompleksowym wskaźnikiem ogólnej wydolności skurczowej jak EF." },
  { targetCategory: 'Podręcznik patofizjologii — Zapalenie', q: 'W kontekście odporności wrodzonej (nieswoistej), co NIE jest jej elementem?', o: ['odpowiedź z udziałem przeciwciał (swoista odpowiedź humoralna)', 'fagocytoza przez neutrofile/makrofagi', 'układ dopełniacza', 'bariery anatomiczne (skóra, błony śluzowe)', 'komórki NK (natural killer)'], a: 0, rationale: "Poprawnie: odpowiedź z udziałem przeciwciał jest elementem odporności SWOISTEJ (nabytej), wymagającej wcześniejszej ekspozycji na antygen i udziału limfocytów B — nie należy do odporności wrodzonej (nieswoistej). Fagocytoza przez neutrofile/makrofagi jest klasycznym, podstawowym mechanizmem odporności wrodzonej, działającym natychmiastowo, nieswoiście. Układ dopełniacza (droga alternatywna) jest elementem odporności wrodzonej, działającym bez wcześniejszej ekspozycji na konkretny antygen. Bariery anatomiczne (skóra, błony śluzowe) są pierwszą linią obrony, klasycznym elementem odporności wrodzonej. Komórki NK są elementem odporności wrodzonej, niszczącym komórki zakażone/nowotworowe bez potrzeby swoistego rozpoznania antygenu jak limfocyty T." },
  { targetCategory: 'Podręcznik patofizjologii — Równowaga kwasowo-zasadowa (RKZ)', q: 'Które zdanie o luce anionowej jest fałszywe?', o: ['liczy się ją ze stężeń wszystkich składników osocza', 'liczy się ją jako różnicę między głównym kationem (Na+) a sumą głównych anionów (Cl- i HCO3-)', 'jej wzrost sugeruje obecność niemierzonych anionów (np. mleczanu, ciał ketonowych)', 'jest przydatna w różnicowaniu przyczyn kwasicy metabolicznej', 'prawidłowa luka anionowa wynosi zwykle ok. 8-16 mmol/L'], a: 0, rationale: "Poprawnie (zdanie fałszywe): luka anionowa liczona jest z ograniczonej liczby GŁÓWNYCH jonów (Na+ minus suma Cl- i HCO3-), NIE ze stężeń wszystkich składników osocza — pomija się w niej mniej licznie występujące jony. Obliczanie luki anionowej jako różnicy między sodem a sumą chlorków i wodorowęglanów jest prawidłową, standardową definicją tego parametru. Wzrost luki anionowej faktycznie sugeruje obecność niemierzonych anionów (np. mleczanu, ciał ketonowych, toksyn), będąc kluczowym narzędziem diagnostycznym — prawdziwe stwierdzenie. Luka anionowa jest faktycznie przydatna w różnicowaniu kwasicy metabolicznej z prawidłową vs zwiększoną luką anionową — prawdziwe zastosowanie kliniczne. Prawidłowa wartość luki anionowej rzeczywiście mieści się w przybliżonym zakresie 8-16 mmol/L — prawdziwe stwierdzenie referencyjne." },
  { targetCategory: 'Podręcznik patofizjologii — Otyłość', q: 'Jaki hormon uwalniany z adipocytów (komórek tłuszczowych) powoduje uczucie sytości?', o: ['leptyna', 'grelina', 'insulina jako główny hormon sytości z adipocytów', 'adiponektyna jako główny hormon sytości', 'kortyzol'], a: 0, rationale: "Poprawnie: leptyna, wydzielana przez adipocyty proporcjonalnie do zasobów tkanki tłuszczowej, działa na podwzgórze, hamując łaknienie i dając uczucie sytości. Grelina jest hormonem OREKSYGENNYM (pobudzającym łaknienie), wydzielanym głównie przez żołądek, nie adipocyty, działającym przeciwnie do leptyny. Insulina jest hormonem trzustkowym regulującym metabolizm glukozy, choć ma pewien wpływ na ośrodek sytości, nie jest głównym, klasycznym hormonem sytości z adipocytów jak leptyna. Adiponektyna jest hormonem adipocytów regulującym wrażliwość na insulinę i metabolizm, nie jest głównym, klasycznym hormonem sytości. Kortyzol jest hormonem stresu z kory nadnerczy, niezwiązanym bezpośrednio z regulacją sytości jako hormon adipocytów." },
  { targetCategory: 'Podręcznik patofizjologii — Cukrzyca', q: 'Gdzie jest wydzielana inkretyna i za co odpowiada?', o: ['wydzielana w jelitach, zwiększa poposiłkowe wydzielanie insuliny', 'wydzielana w trzustce, hamuje wydzielanie insuliny', 'wydzielana w wątrobie, zwiększa glukoneogenezę', 'wydzielana w nerkach, zwiększa wydalanie glukozy', 'wydzielana w żołądku, hamuje motorykę jelit wyłącznie'], a: 0, rationale: "Poprawnie: inkretyny (np. GLP-1, GIP) są hormonami wydzielanymi przez komórki jelitowe w odpowiedzi na posiłek, nasilającymi glukozozależne wydzielanie insuliny przez trzustkę (efekt inkretynowy). Inkretyny nie są wydzielane w trzustce ani nie hamują wydzielania insuliny — działają wręcz przeciwnie, nasilając je. Inkretyny nie są wydzielane w wątrobie ani nie zwiększają glukoneogenezy — to funkcje niezwiązane z ich rzeczywistym działaniem. Inkretyny nie są wydzielane w nerkach ani nie zwiększają wydalania glukozy — to mechanizm niezwiązany z ich rolą fizjologiczną. Inkretyny nie są wydzielane w żołądku, a ich główną funkcją nie jest hamowanie motoryki jelit — to nasilanie wydzielania insuliny." },
  { targetCategory: 'Podręcznik patofizjologii — Nerki i kłębuszkowe zapalenie nerek (KZN)', q: 'Jakie są typowe objawy zespołu nefrytycznego (prawidłowa odpowiedź obejmuje pięć objawów)?', o: ['hematuria, proteinuria, azotemia, nadciśnienie tętnicze, oliguria', 'masywny białkomocz (>3,5g/dobę), hipoalbuminemia, obrzęki, hiperlipidemia, lipiduria', 'wyłącznie bezobjawowy krwiomocz', 'poliuria, polidypsja, hipernatremia, glukozuria, ketonuria', 'hiperkaliemia, hipokalcemia, hiperfosfatemia, kwasica, anemia'], a: 0, rationale: "Poprawnie: pełny obraz zespołu nefrytycznego obejmuje pięć klasycznych elementów: krwiomocz (hematuria), białkomocz (proteinuria), narastającą azotemię, nadciśnienie tętnicze oraz skąpomocz (oliguria), wynikające z zapalnego uszkodzenia kłębuszków. Masywny białkomocz z hipoalbuminemią, obrzękami, hiperlipidemią i lipidurią to zespół NERCZYCOWY, odrębna jednostka o innym mechanizmie. Zespół nefrytyczny nie jest bezobjawowym izolowanym krwiomoczem — towarzyszy mu istotny, złożony zestaw objawów klinicznych. Poliuria, polidypsja, hipernatremia, glukozuria i ketonuria są typowe dla cukrzycy, niezwiązane z zespołem nefrytycznym. Zestaw hiperkaliemii, hipokalcemii, hiperfosfatemii, kwasicy i anemii jest bardziej typowy dla zaawansowanej, przewlekłej niewydolności nerek, nie klasycznej definicji zespołu nefrytycznego." },
  { targetCategory: 'Podręcznik patofizjologii — Jakościowe zaburzenia wentylacji', q: 'Odma opłucnowa (obecność powietrza w jamie opłucnej) powoduje jaki typ zaburzenia wentylacyjnego płuca po stronie odmy?', o: ['restrykcję płucną (zapadnięcie płuca)', 'obturację dróg oddechowych', 'restrykcję pozapłucną', 'jakościowe zaburzenie wentylacji typu mieszanego z przewagą obturacji', 'brak wpływu na mechanikę oddychania'], a: 0, rationale: "Poprawnie: odma opłucnowa powoduje zapadnięcie się płuca po stronie odmy (utrata ujemnego ciśnienia w jamie opłucnej), co jest mechanizmem restrykcyjnym — zmniejszeniem objętości czynnościowej płuca. Obturacja dotyczy zwężenia dróg oddechowych, niezwiązanego z mechanizmem odmy opłucnowej (zapadnięcia całego płuca). Restrykcja pozapłucna dotyczy ograniczeń ze strony klatki piersiowej/mięśni/otyłości, podczas gdy odma powoduje bezpośredni problem WEWNĄTRZ jamy opłucnej wpływający na samo płuco, co klasyfikuje się jako restrykcję związaną z samym płucem/opłucną. Odma nie jest mieszanym zaburzeniem z przewagą obturacji — jej dominującym mechanizmem jest restrykcja z powodu zapadnięcia płuca. Odma opłucnowa ma istotny, poważny wpływ na mechanikę oddychania, więc stwierdzenie o braku wpływu jest nieprawdziwe." },
  { targetCategory: 'Podręcznik patofizjologii — Anemia i policytemia', q: 'Jaki jest skutek niedoboru hepcydyny dla gospodarki żelazem?', o: ['zwiększone uwalnianie żelaza z makrofagów do osocza i zwiększone wchłanianie jelitowe', 'zmniejszone uwalnianie żelaza z makrofagów do osocza i wydalanie żelaza z kałem', 'brak wpływu na gospodarkę żelazem', 'zwiększone magazynowanie żelaza w makrofagach bez uwalniania', 'zahamowanie wchłaniania żelaza w jelicie'], a: 0, rationale: "Poprawnie: niedobór hepcydyny znosi jej hamujące działanie na ferroportynę, co zwiększa uwalnianie żelaza z makrofagów do osocza oraz zwiększa jego wchłanianie jelitowe — mechanizm leżący u podstaw hemochromatozy. Zmniejszone uwalnianie żelaza i jego wydalanie z kałem jest odwróceniem rzeczywistego mechanizmu — to WYSOKA, nie niska hepcydyna blokuje uwalnianie żelaza (jak w anemii chorób przewlekłych). Hepcydyna ma kluczowy, dobrze udokumentowany wpływ na gospodarkę żelazem, więc stwierdzenie braku wpływu jest nieprawdziwe. Niedobór hepcydyny prowadzi do UWALNIANIA, nie magazynowania żelaza w makrofagach — to odwrócenie mechanizmu. Niedobór hepcydyny ZWIĘKSZA, nie hamuje wchłanianie żelaza w jelicie." },
  { targetCategory: 'Podręcznik patofizjologii — Anemia i policytemia', q: 'Jakie białko jest główną przyczyną niedokrwistości w przebiegu chorób przewlekłych (zapalnych)?', o: ['hepcydyna', 'transferyna', 'ferrytyna', 'erytropoetyna', 'haptoglobina'], a: 0, rationale: "Poprawnie: w przewlekłych chorobach zapalnych podwyższona hepcydyna blokuje uwalnianie żelaza z magazynów i jego wchłanianie jelitowe, prowadząc do czynnościowego niedoboru żelaza i niedokrwistości chorób przewlekłych. Transferyna transportuje żelazo we krwi, ale jej zmiany są wtórne do działania hepcydyny, nie są głównym mechanizmem sprawczym anemii. Ferrytyna magazynuje żelazo i wzrasta jako reagent ostrej fazy, ale to hepcydyna jest głównym mechanizmem blokującym dostępność żelaza. Erytropoetyna bywa względnie niewystarczająca w tej anemii, ale nie jest głównym, pierwotnym mechanizmem sprawczym w porównaniu z hepcydyną. Haptoglobina wiąże wolną hemoglobinę przy hemolizie, niezwiązana z mechanizmem anemii chorób przewlekłych." },
  { targetCategory: 'Podręcznik patofizjologii — Wątroba', q: 'Które zdanie o funkcjach wątroby jest fałszywe?', o: ['wątroba wytwarza immunoglobuliny (IgG)', 'wątroba wytwarza albuminy', 'wątroba wytwarza czynniki krzepnięcia', 'wątroba magazynuje glikogen', 'wątroba syntetyzuje kwasy żółciowe z cholesterolu'], a: 0, rationale: "Poprawnie (zdanie fałszywe): immunoglobuliny (przeciwciała, w tym IgG) są produkowane przez limfocyty B/plazmocyty, NIE przez wątrobę — to istotne odróżnienie od innych białek osocza rzeczywiście produkowanych przez wątrobę. Wątroba faktycznie wytwarza albuminy, będące jej głównym produktem białkowym — prawdziwe stwierdzenie. Wątroba faktycznie wytwarza większość czynników krzepnięcia (fibrynogen, protrombinę, czynniki VII, IX, X i inne) — prawdziwe stwierdzenie. Wątroba faktycznie magazynuje glikogen jako rezerwę energetyczną, uwalniany podczas głodzenia — prawdziwe stwierdzenie. Wątroba faktycznie syntetyzuje kwasy żółciowe z cholesterolu, będące podstawą ich obiegu jelitowo-wątrobowego — prawdziwe stwierdzenie." },
  { targetCategory: 'Skrypt — Fizjologia układu krążenia', q: 'Który skrót opisuje ilość krwi w lewej komorze tuż przed jej skurczem?', o: ['EDV (objętość końcoworozkurczowa)', 'ESV (objętość końcowoskurczowa)', 'CO (rzut minutowy serca)', 'SV (objętość wyrzutowa)', 'MAP (średnie ciśnienie tętnicze)'], a: 0, rationale: "Poprawnie: EDV (objętość końcoworozkurczowa) to ilość krwi w komorze bezpośrednio przed jej skurczem, na końcu fazy napełniania rozkurczowego. ESV (objętość końcowoskurczowa) to ilość krwi POZOSTAJĄCA w komorze PO skurczu, nie przed nim — odwrotny moment cyklu. CO (rzut minutowy) to całkowita objętość krwi wypompowywana przez serce w ciągu minuty, nie objętość w komorze w danym momencie. SV (objętość wyrzutowa) to różnica między EDV a ESV (ilość wyrzuconej krwi podczas skurczu), nie sama objętość przed skurczem. MAP (średnie ciśnienie tętnicze) jest parametrem ciśnieniowym, niezwiązanym bezpośrednio z objętością krwi w komorze." },
  { targetCategory: 'Podręcznik patofizjologii — Przysadka i tarczyca', q: 'Które hormony NIE są magazynowane w ziarnistościach wydzielniczych, lecz produkowane na bieżąco zgodnie z zapotrzebowaniem?', o: ['hormony steroidowe (np. kortyzol, aldosteron, hormony płciowe)', 'hormony peptydowe (np. insulina, ACTH)', 'katecholaminy (adrenalina, noradrenalina)', 'hormony tarczycy magazynowane w tyreoglobulinie', 'hormon wzrostu (GH)'], a: 0, rationale: "Poprawnie: hormony steroidowe (lipofilne, np. kortyzol, aldosteron, hormony płciowe) nie są magazynowane w ziarnistościach wydzielniczych — są syntetyzowane i natychmiast uwalniane zgodnie z bieżącym zapotrzebowaniem, z powodu ich zdolności do swobodnej dyfuzji przez błony komórkowe. Hormony peptydowe (jak insulina, ACTH) są klasycznie magazynowane w ziarnistościach wydzielniczych przed uwolnieniem w odpowiedzi na bodziec. Katecholaminy są magazynowane w ziarnistościach chromochłonnych rdzenia nadnerczy przed uwolnieniem. Hormony tarczycy są magazynowane w postaci związanej z tyreoglobuliną w koloidzie pęcherzyków tarczycy, będąc wyjątkowym przykładem zewnątrzkomórkowego magazynowania. Hormon wzrostu, jako hormon peptydowy, jest magazynowany w ziarnistościach wydzielniczych somatotropów przysadki." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Jakim neuroprzekaźnikiem posługują się neurony gruszkowate (Purkinjego) kory móżdżku i jaki jest ich efekt na jądra przedsionkowe?', o: ['GABA, hamują jądra przedsionkowe', 'glutaminian, pobudzają jądra przedsionkowe', 'acetylocholina, hamują jądra przedsionkowe', 'dopamina, pobudzają jądra przedsionkowe', 'serotonina, nie wpływają na jądra przedsionkowe'], a: 0, rationale: "Poprawnie: neurony Purkinjego kory móżdżku są GABA-ergiczne (hamujące) i wywierają hamujący wpływ na jądra przedsionkowe oraz inne jądra głębokie móżdżku, regulując precyzję i koordynację ruchu. Glutaminian jest neuroprzekaźnikiem POBUDZAJĄCYM, przeciwnym do hamującego GABA używanego przez komórki Purkinjego. Acetylocholina nie jest głównym neuroprzekaźnikiem komórek Purkinjego — te komórki klasycznie wykorzystują GABA. Dopamina nie jest neuroprzekaźnikiem komórek Purkinjego ani nie pobudza jąder przedsionkowych w tym mechanizmie. Serotonina nie jest głównym neuroprzekaźnikiem komórek Purkinjego, a te komórki mają istotny, hamujący wpływ na jądra przedsionkowe, nie brak wpływu." },
  { targetCategory: 'Prezentacje — Regulacja układu krążenia', q: 'Która substancja NIE powoduje rozkurczu tętnic wieńcowych?', o: ['endotelina', 'prostaglandyna E (PGE)', 'acetylocholina (na prawidłowy śródbłonek)', 'tlenek azotu (NO)', 'adenozyna'], a: 0, rationale: "Poprawnie: endotelina jest jednym z najsilniejszych znanych czynników KURCZĄCYCH naczynia (w tym wieńcowe), działającym przeciwnie do rozkurczu. Prostaglandyna E ma działanie rozszerzające naczynia wieńcowe, przyczyniając się do regulacji przepływu wieńcowego. Acetylocholina, działając na prawidłowy śródbłonek, powoduje uwalnianie NO i rozkurcz naczyń wieńcowych. Tlenek azotu jest kluczowym, silnym mediatorem rozkurczu naczyń wieńcowych, wydzielanym przez śródbłonek. Adenozyna, uwalniana przy niedotlenieniu mięśnia sercowego, jest silnym miejscowym czynnikiem rozszerzającym naczynia wieńcowe." },
  { targetCategory: 'Prezentacje — Fizjologia układu pokarmowego', q: 'Jakie jest działanie nerwu błędnego na motorykę żołądka?', o: ['pobudza motorykę i wydzielanie żołądkowe', 'hamuje motorykę i wydzielanie żołądkowe', 'nie ma wpływu na motorykę żołądka', 'wpływa wyłącznie na zwieracz odźwiernika, nie na perystaltykę trzonu', 'działa wyłącznie hamująco na wydzielanie, bez wpływu na perystaltykę'], a: 0, rationale: "Poprawnie: nerw błędny (przywspółczulny) pobudza motorykę żołądka i nasila wydzielanie soku żołądkowego, będąc kluczowym elementem fazy głowowej trawienia. Twierdzenie o działaniu hamującym jest odwróceniem rzeczywistego, pobudzającego wpływu przywspółczulnego unerwienia żołądka. Nerw błędny ma istotny, dobrze udokumentowany wpływ na czynność żołądka, więc stwierdzenie braku wpływu jest nieprawdziwe. Nerw błędny wpływa zarówno na zwieracz odźwiernika, jak i na perystaltykę trzonu żołądka, nie wybiórczo tylko na zwieracz. Nerw błędny nasila, a nie hamuje wydzielanie, i wpływa również na perystaltykę, nie tylko na wydzielanie." },
  { targetCategory: 'Podręcznik patofizjologii — Przewód pokarmowy', q: 'Jaki peptyd wywołuje reakcję immunologiczną w celiakii?', o: ['gliadyna (frakcja glutenu)', 'białko mleka krowiego', 'laktoza', 'gluten jako całość, bez rozróżnienia frakcji', 'skrobia pszenna'], a: 0, rationale: "Poprawnie: gliadyna, frakcja białkowa glutenu, wywołuje w celiakii nieprawidłową odpowiedź immunologiczną prowadzącą do uszkodzenia kosmków jelitowych. Białko mleka krowiego jest związane z odrębną alergią pokarmową, niezwiązaną z mechanizmem celiakii. Laktoza jest cukrem, którego nietolerancja wynika z niedoboru enzymu laktazy, mechanizm zupełnie odrębny od autoimmunologicznej reakcji na gliadynę w celiakii. Gluten jako całość zawiera różne frakcje białkowe, ale to konkretnie GLIADYNA jest swoistym, immunogennym elementem wywołującym celiakię, nie cały gluten w sposób niezróżnicowany. Skrobia pszenna jest węglowodanem, niezwiązanym z mechanizmem immunologicznym celiakii." },
  { targetCategory: 'Wykład 15 — Niewydolność oddechowa', q: 'Jaki jest mechanizm odruchu Eulera-Liljestranda?', o: ['skurcz naczyń płucnych w odpowiedzi na miejscową hipoksję pęcherzykową', 'rozkurcz naczyń płucnych w odpowiedzi na miejscową hipoksję pęcherzykową', 'skurcz naczyń systemowych w odpowiedzi na hipoksję', 'rozkurcz oskrzeli w odpowiedzi na hipoksję', 'zwiększenie częstości oddechów w odpowiedzi na hiperkapnię'], a: 0, rationale: "Poprawnie: odruch Eulera-Liljestranda (skurcz hipoksyczny naczyń płucnych) polega na miejscowym skurczu naczyń płucnych w odpowiedzi na obniżoną prężność tlenu w danym obszarze pęcherzyków, przekierowując krew do lepiej wentylowanych obszarów płuc — unikalny mechanizm odwrotny do reakcji naczyń systemowych. Rozkurcz naczyń płucnych w odpowiedzi na hipoksję jest odwróceniem rzeczywistego, unikalnego mechanizmu tego odruchu. W naczyniach SYSTEMOWYCH hipoksja powoduje ROZKURCZ (nie skurcz) — to właśnie odróżnia krążenie płucne (paradoksalny skurcz) od systemowego, więc to zdanie opisuje mechanizm przeciwny do faktycznego w krążeniu systemowym. Odruch Eulera-Liljestranda dotyczy naczyń płucnych, nie bezpośrednio rozkurczu oskrzeli. Odruch ten jest mechanizmem naczyniowym (skurcz naczyń), nie bezpośrednio związanym z regulacją częstości oddechów w odpowiedzi na CO2." },
  { targetCategory: 'Skrypt — Fizjologia oddychania (zaawansowana)', q: 'Jakie receptory pośredniczą w odczuwaniu duszności?', o: ['mechanoreceptory J oraz wolno i szybko adaptujące się receptory rozciągowe (SAR/RAR)', 'wyłącznie chemoreceptory obwodowe', 'wyłącznie baroreceptory', 'wyłącznie receptory bólowe skóry klatki piersiowej', 'wyłącznie receptory węchowe'], a: 0, rationale: "Poprawnie: odczuwanie duszności jest złożonym zjawiskiem integrującym sygnały z receptorów J (okołowłośniczkowych), wolno adaptujących się receptorów rozciągowych (SAR) i szybko adaptujących się receptorów podrażnieniowych (RAR) w płucach, obok informacji chemoreceptorowej. Same chemoreceptory obwodowe nie oddają pełnego, złożonego mechanizmu percepcji duszności, pomijając istotny wkład receptorów płucnych. Baroreceptory reagują na ciśnienie krwi, niezwiązane bezpośrednio z percepcją duszności jako takiej. Receptory bólowe skóry klatki piersiowej nie są głównym mechanizmem percepcji duszności, będącej odczuciem związanym z układem oddechowym, nie skórnym czuciem bólu. Receptory węchowe są niezwiązane z percepcją duszności, dotycząc zmysłu powonienia." },
  { targetCategory: 'Podręcznik patofizjologii — Wątroba', q: 'Smoliste, czarne stolce (melena) są objawem czego?', o: ['krwawienia z górnego odcinka przewodu pokarmowego', 'krwawienia z dolnego odcinka przewodu pokarmowego', 'biegunki tłuszczowej', 'zaparcia nawykowego', 'zakażenia pasożytniczego bez krwawienia'], a: 0, rationale: "Poprawnie: smoliste, czarne stolce (melena) powstają, gdy krew z krwawienia w górnym odcinku przewodu pokarmowego ulega trawieniu przez enzymy i kwas żołądkowy podczas pasażu jelitowego, przybierając charakterystyczną czarną barwę. Krwawienie z dolnego odcinka przewodu pokarmowego daje typowo krew jasnoczerwoną, niezmienioną przez trawienie, nie smoliste stolce. Biegunka tłuszczowa daje charakterystyczne, tłuste, cuchnące stolce, niezwiązane z obecnością strawionej krwi. Zaparcie nawykowe nie daje charakterystycznego, czarnego zabarwienia stolca związanego z krwią. Zakażenie pasożytnicze bez krwawienia nie powoduje typowo smolistego zabarwienia stolca." },
  { targetCategory: 'Podręcznik patofizjologii — Cukrzyca', q: 'Dlaczego poziom glukozy na czczo po nocy jest podwyższony u osób z cukrzycą (zjawisko brzasku)?', o: ['nocny wzrost hormonów kontrregulacyjnych (kortyzol, GH) przy niewystarczającej insulinie', 'nocne nasilenie wydzielania insuliny przewyższające zapotrzebowanie', 'brak jakiegokolwiek wpływu rytmu dobowego na glikemię', 'nocny spadek wchłaniania glukozy z przewodu pokarmowego jako główny mechanizm', 'nocna hipoglikemia reaktywna jako jedyny mechanizm'], a: 0, rationale: "Poprawnie: zjawisko brzasku (dawn phenomenon) wynika z fizjologicznego, nocnego/wczesnorannego wzrostu hormonów kontrregulacyjnych (kortyzolu, hormonu wzrostu), które u osób z cukrzycą, przy niewystarczającej ilości/działaniu insuliny, podnoszą glikemię poranną. Nasilone wydzielanie insuliny przewyższające zapotrzebowanie obniżałoby, nie podwyższało glikemię — to odwrócenie mechanizmu (a przy cukrzycy typu 1 insulina endogenna jest zresztą niedostateczna). Rytm dobowy hormonów istotnie wpływa na glikemię (stąd zjawisko brzasku), więc stwierdzenie braku wpływu jest nieprawdziwe. Nocne wchłanianie glukozy z przewodu pokarmowego nie jest głównym mechanizmem tego zjawiska (pacjent zwykle nie je w nocy) — kluczowe są zmiany hormonalne. Zjawisko brzasku nie jest hipoglikemią reaktywną (efektem Somogyi, odrębnym mechanizmem) — jest bezpośrednim skutkiem hormonalnego wzrostu glikemii, nie odpowiedzią na wcześniejszą hipoglikemię." },
  { targetCategory: 'Podręcznik patofizjologii — Skazy krwotoczne', q: 'Co się dzieje przy niedoborze witaminy K?', o: ['zmniejszona synteza czynników krzepnięcia II, VII, IX, X w wątrobie', 'zwiększona synteza czynnika V w wątrobie jako mechanizm kompensacyjny', 'brak wpływu na syntezę czynników krzepnięcia', 'zwiększona aktywność czynników zależnych od witaminy K', 'zaburzenie wyłącznie hemostazy pierwotnej (płytkowej)'], a: 0, rationale: "Poprawnie: witamina K jest niezbędnym kofaktorem karboksylacji (aktywacji) czynników krzepnięcia II, VII, IX i X w wątrobie — jej niedobór zmniejsza syntezę FUNKCJONALNYCH form tych czynników, prowadząc do skazy osoczowej. Czynnik V nie jest zależny od witaminy K (jest jednym z niewielu czynników krzepnięcia niezależnych od tego kofaktora), więc jego synteza nie jest kompensacyjnie zwiększana w odpowiedzi na niedobór witaminy K. Niedobór witaminy K ma istotny, dobrze udokumentowany wpływ na syntezę czynników krzepnięcia, więc stwierdzenie braku wpływu jest nieprawdziwe. Niedobór witaminy K ZMNIEJSZA, nie zwiększa aktywność zależnych od niej czynników krzepnięcia — to odwrócenie mechanizmu. Niedobór witaminy K wpływa na hemostazę WTÓRNĄ (osoczową kaskadę krzepnięcia), nie bezpośrednio na hemostazę pierwotną (płytkową)." },
  { targetCategory: 'Skrypt — Fizjologia nerek', q: 'W jakiej jednostce wyraża się klirens nerkowy?', o: ['mL/min', 'mg/dL', 'mmol/L', 'mOsm/L', 'g/dobę'], a: 0, rationale: "Poprawnie: klirens nerkowy wyraża się w jednostkach objętości na czas (mL/min), odzwierciedlając objętość osocza całkowicie oczyszczaną z danej substancji w jednostce czasu. mg/dL jest jednostką stężenia substancji, nie klirensu (objętościowego tempa oczyszczania). mmol/L jest jednostką stężenia molowego, nie klirensu. mOsm/L jest jednostką osmolarności, niezwiązaną z jednostką klirensu. g/dobę jest jednostką całkowitej wydalonej masy substancji na dobę, odmienną koncepcyjnie od klirensu (objętości oczyszczanej na jednostkę czasu)." },
  { targetCategory: 'Podręcznik patofizjologii — Nadkrzepliwość', q: 'Co to jest triada Virchowa?', o: ['nadkrzepliwość krwi, uszkodzenie śródbłonka naczynia i zaburzony (burzliwy/zwolniony) przepływ krwi', 'niedobór żelaza, witaminy B12 i kwasu foliowego', 'trzy fazy hemostazy: naczyniowa, płytkowa, osoczowa', 'trzy typy wstrząsu: hipowolemiczny, kardiogenny, dystrybucyjny', 'trzy mechanizmy gorączki: egzogenna, endogenna, ośrodkowa'], a: 0, rationale: "Poprawnie: triada Virchowa opisuje trzy główne czynniki sprzyjające tworzeniu zakrzepów: nadkrzepliwość krwi, uszkodzenie śródbłonka naczynia i zaburzony (zastój lub turbulentny) przepływ krwi. Niedobór żelaza, B12 i folianów to przyczyny różnych typów niedokrwistości, niezwiązane z triadą Virchowa dotyczącą zakrzepicy. Trzy fazy hemostazy to odrębna klasyfikacja procesu krzepnięcia, nie triada Virchowa dotycząca czynników ryzyka zakrzepicy. Klasyfikacja typów wstrząsu jest odrębnym zagadnieniem, niezwiązanym z triadą Virchowa. Mechanizmy gorączki są odrębnym tematem patofizjologicznym, niezwiązanym z triadą czynników zakrzepowych Virchowa." },
  { targetCategory: 'Wykład 11 — Zaburzenia rytmu serca (arytmie)', q: 'Jak w EKG objawia się zahamowanie zatokowe (zatrzymanie węzła SA)?', o: ['pauza w rytmie bez generowania załamka P, niebędąca wielokrotnością prawidłowego odstępu P-P', 'regularna pauza będąca dokładną wielokrotnością odstępu P-P (blok SA)', 'stałe wydłużenie odstępu PQ', 'poszerzenie zespołów QRS bez zmiany załamka P', 'brak jakichkolwiek zmian w zapisie EKG'], a: 0, rationale: "Poprawnie: zahamowanie zatokowe (zatrzymanie węzła SA) daje nieregularną pauzę w rytmie, NIEBĘDĄCĄ dokładną wielokrotnością prawidłowego odstępu P-P, ponieważ węzeł SA całkowicie przestaje generować impulsy na pewien czas. Pauza będąca dokładną wielokrotnością odstępu P-P jest charakterystyczna dla BLOKU zatokowo-przedsionkowego (impuls jest generowany, ale nie wyprowadzony), odrębnego zjawiska od całkowitego zahamowania (zatrzymania) węzła SA. Stałe wydłużenie PQ opisuje blok AV I stopnia, niezwiązane z zahamowaniem węzła zatokowego. Poszerzenie QRS jest niezwiązane z zahamowaniem zatokowym, które dotyczy generowania impulsu w węźle SA, nie przewodzenia komorowego. Zahamowanie zatokowe daje wyraźną, charakterystyczną zmianę w zapisie EKG (pauzę), więc stwierdzenie o braku zmian jest nieprawdziwe." },
  { targetCategory: 'Wykład 14 — Zaburzenia wymiany gazowej', q: 'O czym może świadczyć odma opłucnowa obejmująca jedno płuco?', o: ['o obecności powietrza w jamie opłucnej po stronie zajętej, powodującej zapadnięcie tego płuca', 'o obustronnym zapadnięciu obu płuc jednocześnie', 'o prawidłowej funkcji oddechowej bez żadnych zaburzeń', 'o zwiększonej wentylacji obu płuc', 'o zator tętnicy płucnej jako jedynej możliwej przyczynie'], a: 0, rationale: "Poprawnie: jednostronna odma opłucnowa wskazuje na obecność powietrza w jamie opłucnej po stronie zajętej, powodującą utratę ujemnego ciśnienia i zapadnięcie się tego jednego płuca. Odma jednego płuca z definicji dotyczy jednej strony, nie obustronnego zapadnięcia obu płuc jednocześnie (co byłoby znacznie rzadszym, obustronnym zjawiskiem). Odma opłucnowa jest istotnym zaburzeniem czynnościowym płuca, więc stwierdzenie o prawidłowej funkcji oddechowej bez zaburzeń jest nieprawdziwe. Odma zmniejsza, nie zwiększa efektywną wentylację zajętego płuca (i pośrednio funkcję oddechową ogólnie), z powodu jego zapadnięcia. Odma opłucnowa ma odrębny mechanizm (obecność powietrza w jamie opłucnej, np. z urazu) od zatoru tętnicy płucnej (zablokowania naczynia przez skrzeplinę) — to różne jednostki chorobowe." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Co jest wydzielane na zakończeniu (zazwojowym) włókna współczulnego (w typowym unerwieniu)?', o: ['noradrenalina (NA)', 'acetylocholina', 'dopamina', 'serotonina', 'histamina'], a: 0, rationale: "Poprawnie: typowe zazwojowe włókna współczulne uwalniają noradrenalinę jako główny neuroprzekaźnik działający na receptory adrenergiczne narządów docelowych. Acetylocholina jest neuroprzekaźnikiem PRZEDZWOJOWYM (zarówno współczulnym, jak i przywspółczulnym) oraz nietypowym wyjątkiem zazwojowym (np. gruczoły potowe), ale nie jest typowym neuroprzekaźnikiem większości zazwojowych włókien współczulnych. Dopamina jest prekursorem noradrenaliny i adrenaliny oraz odrębnym neuroprzekaźnikiem w OUN, ale nie jest głównym neuroprzekaźnikiem typowych zazwojowych włókien współczulnych obwodowych. Serotonina nie jest głównym neuroprzekaźnikiem zazwojowych włókien współczulnych. Histamina jest mediatorem uwalnianym przez mastocyty w reakcjach alergicznych/zapalnych, niezwiązanym z typowym przekaźnictwem współczulnym." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Jaki rodzaj włókien nerwowych odpowiada za precyzyjne odbieranie bodźców czuciowych (dotyk) i czucie głębokie (proprioception)?', o: ['włókna mielinowe A-beta', 'włókna bezmielinowe C', 'włókna mielinowe A-delta', 'włókna B (przedzwojowe autonomiczne)', 'włókna A-gamma (do wrzecion mięśniowych)'], a: 0, rationale: "Poprawnie: grube, silnie zmielinizowane włókna A-beta przewodzą precyzyjne informacje o dotyku i czuciu głębokim (propriocepcji) z dużą szybkością przewodzenia. Włókna bezmielinowe C są najwolniejsze, przewodzące wolny, tępy ból i temperaturę, nie precyzyjne czucie dotyku/głębokie. Włókna A-delta przewodzą szybki, ostry ból i temperaturę, cieńsze i wolniejsze niż A-beta, nie są głównym nośnikiem precyzyjnego czucia dotyku. Włókna B są przedzwojowymi włóknami autonomicznymi, niezwiązanymi z czuciem somatycznym (dotyk/propriocepcja). Włókna A-gamma unerwiają ruchowo wrzeciona mięśniowe (funkcja efektorowa), nie są głównym nośnikiem czucia dotyku/propriocepcji (tę funkcję pełnią włókna czuciowe Ia/II z wrzecion, ale to odrębna klasyfikacja niż A-beta dla skóry)." },
  { targetCategory: 'Wykład 9 — Patofizjologia wstrząsu', q: 'Co się dzieje w wyniku odruchu Bezolda-Jarischa?', o: ['bradykardia i rozszerzenie naczyń krwionośnych', 'tachykardia i skurcz naczyń krwionośnych', 'wyłącznie tachykardia bez wpływu na naczynia', 'wyłącznie skurcz naczyń bez wpływu na rytm serca', 'zatrzymanie akcji serca jako jedyny efekt'], a: 0, rationale: "Poprawnie: odruch Bezolda-Jarischa, wyzwalany pobudzeniem mechanoreceptorów lewej komory, powoduje bradykardię i rozszerzenie naczyń krwionośnych, mogąc prowadzić do hipotensji i omdlenia. Tachykardia i skurcz naczyń są odwróceniem rzeczywistego, hamującego kierunku działania tego odruchu. Odruch ten wpływa jednocześnie na rytm serca i napięcie naczyń — ograniczenie wyłącznie do tachykardii pomija istotny komponent naczyniowy (i błędnie odwraca kierunek zmiany rytmu). Odruch ten wpływa jednocześnie na naczynia i rytm serca — ograniczenie wyłącznie do skurczu naczyń bez wpływu na rytm pomija kluczowy komponent bradykardyczny. Odruch ten nie powoduje typowo całkowitego zatrzymania akcji serca jako jedynego, izolowanego efektu — daje bradykardię, nie asystolię, w typowym przebiegu." },
  { targetCategory: 'Skrypt — Fizjologia układu krążenia', q: 'Co NIE wpływa na wielkość powrotu żylnego do serca?', o: ['masa ciała pacjenta jako bezpośredni czynnik', 'pozycja ciała', 'ciśnienie w klatce piersiowej', 'objętość krwi w łożysku naczyniowym', 'napięcie mięśni szkieletowych (pompa mięśniowa)'], a: 0, rationale: "Poprawnie: sama masa ciała pacjenta nie jest bezpośrednim, klasycznym czynnikiem wpływającym na powrót żylny — to inne parametry hemodynamiczne (ciśnienie, pozycja, objętość krwi) mają bezpośredni wpływ, nie ogólna masa ciała jako taka. Pozycja ciała istotnie wpływa na powrót żylny (np. pionizacja zmniejsza go z powodu grawitacyjnego zalegania krwi w kończynach dolnych). Ciśnienie w klatce piersiowej (np. podczas oddychania, próby Valsalvy) istotnie wpływa na powrót żylny poprzez gradient ciśnień. Objętość krwi w łożysku naczyniowym bezpośrednio determinuje ilość krwi dostępnej do powrotu żylnego. Napięcie mięśni szkieletowych (pompa mięśniowa) istotnie wspomaga powrót żylny, zwłaszcza z kończyn dolnych, poprzez mechaniczny ucisk na żyły." },
  { targetCategory: 'Wykład 16 — Jakościowe zaburzenia wentylacji (obturacja i restrykcja)', q: 'Jaki jest wzór na wskaźnik Tiffeneau?', o: ['FEV1/VC × 100%', 'VC/FEV1 × 100%', 'FEV1/TLC × 100%', 'RV/TLC × 100%', 'FEV1 × VC'], a: 0, rationale: "Poprawnie: wskaźnik Tiffeneau to stosunek natężonej objętości wydechowej pierwszosekundowej (FEV1) do pojemności życiowej (VC), wyrażony w procentach — kluczowy parametr różnicujący obturację od restrykcji. Odwrócenie wzoru (VC/FEV1) daje wartość matematycznie odwrotną, niezgodną ze standardową definicją tego wskaźnika. Stosunek FEV1/TLC nie jest standardową definicją wskaźnika Tiffeneau — to inny, mniej powszechnie stosowany parametr. Stosunek RV/TLC jest odrębnym parametrem oceniającym stopień pułapki powietrznej, niezwiązanym z definicją wskaźnika Tiffeneau. Iloczyn FEV1 i VC nie ma sensu fizjologicznego jako wskaźnik diagnostyczny — wskaźnik Tiffeneau to stosunek (iloraz), nie iloczyn tych wartości." },
  { targetCategory: 'Prezentacje — Fizjologia krwi', q: 'Osoba pojechała w wysokie góry na 2 tygodnie. Jakie zmiany morfologii krwi zaobserwujemy po powrocie?', o: ['RBC wzrośnie, WBC bez zmian, MCV bez zmian, hematokryt wzrośnie', 'RBC zmaleje, WBC wzrośnie znacznie, MCV wzrośnie, hematokryt zmaleje', 'wszystkie parametry pozostaną bez zmian', 'RBC wzrośnie, ale hematokryt zmaleje', 'WBC wzrośnie jako jedyna, izolowana zmiana'], a: 0, rationale: "Poprawnie: przewlekła hipoksja na dużej wysokości pobudza erytropoetynę, zwiększając liczbę erytrocytów (RBC) i hematokryt (odpowiedź adaptacyjna), bez istotnego wpływu na liczbę leukocytów (WBC) czy średnią objętość erytrocytu (MCV, ponieważ mechanizm to zwiększona PRODUKCJA erytrocytów, nie zmiana ich wielkości). Spadek RBC ze wzrostem WBC i MCV jest sprzeczny z fizjologiczną, dobrze udokumentowaną odpowiedzią adaptacyjną na wysokościową hipoksję. Ekspozycja na dużą wysokość wywołuje istotne, mierzalne zmiany morfologii krwi (wzrost RBC/hematokrytu), więc stwierdzenie braku zmian jest nieprawdziwe. Wzrost RBC musi iść w parze ze wzrostem, nie spadkiem hematokrytu — te dwa parametry są ze sobą ściśle powiązane (więcej erytrocytów = wyższy hematokryt). Izolowany wzrost WBC bez zmian erytrocytarnych nie oddaje typowej, dobrze udokumentowanej odpowiedzi adaptacyjnej na hipoksję wysokościową, która dotyczy głównie linii czerwonokrwinkowej." },
  { targetCategory: 'Podręcznik patofizjologii — Wątroba', q: 'Fototerapia (naświetlanie UV) jest stosowana w żółtaczce noworodków. Na czym polega jej mechanizm działania?', o: ['przekształca bilirubinę wolną w izomery rozpuszczalne w wodzie, ułatwiając jej wydalanie bez sprzęgania', 'przyspiesza dojrzewanie enzymów wątrobowych sprzęgających bilirubinę', 'niszczy nadmiar erytrocytów odpowiedzialnych za produkcję bilirubiny', 'hamuje wchłanianie zwrotne bilirubiny w jelitach jako główny mechanizm', 'nasila hemolizę fizjologiczną noworodka'], a: 0, rationale: "Poprawnie: światło UV przekształca nierozpuszczalną w wodzie bilirubinę wolną w izomery fotochemiczne rozpuszczalne w wodzie, które mogą być wydalone z moczem i żółcią bez konieczności enzymatycznego sprzęgania w wątrobie. Fototerapia nie działa poprzez przyspieszenie dojrzewania enzymów wątrobowych — działa bezpośrednio na bilirubinę w skórze, niezależnie od dojrzałości układu enzymatycznego wątroby. Fototerapia nie niszczy erytrocytów — żółtaczka fizjologiczna wynika częściowo z nasilonego rozpadu erytrocytów noworodka, ale fototerapia tego nie nasila ani nie jest to jej mechanizm. Fototerapia nie działa głównie poprzez hamowanie wchłaniania jelitowego bilirubiny jako główny mechanizm. Fototerapia nie nasila hemolizy — działa na już krążącą bilirubinę, przekształcając ją chemicznie, nie wpływając na tempo rozpadu erytrocytów." },
  { targetCategory: 'Podręcznik patofizjologii — Woda i sód', q: 'Jaki rodzaj obrzęku obserwujemy przy obrzęku dłoni w gorący dzień?', o: ['obrzęk z przekrwienia czynnego', 'obrzęk z przekrwienia biernego', 'obrzęk limfatyczny', 'obrzęk niedoborowy (z hipoalbuminemii)', 'obrzęk zapalny'], a: 0, rationale: "Poprawnie: w upalny dzień dochodzi do termoregulacyjnego rozszerzenia naczyń skóry (przekrwienia czynnego) i zwiększonego napływu krwi tętniczej, powodującego łagodny obrzęk dłoni. Przekrwienie bierne wynika z utrudnionego odpływu żylnego (np. niewydolność serca), niezwiązane z reakcją termoregulacyjną na upał. Obrzęk limfatyczny wynika z zablokowania odpływu chłonki, niezwiązanego z przejściową reakcją na wysoką temperaturę. Obrzęk niedoborowy jest efektem hipoalbuminemii, niezwiązanym z temperaturą otoczenia. Obrzęk zapalny towarzyszy procesom zapalnym, nie samej wazodylatacji termoregulacyjnej." },
  { targetCategory: 'Podręcznik patofizjologii — EKG: załamki, odcinki, odstępy', q: 'Dlaczego w odprowadzeniu I obserwujemy fizjologiczny załamek Q (Q przegrodowe)?', o: ['odzwierciedla wczesną depolaryzację przegrody międzykomorowej od lewej do prawej strony', 'odzwierciedla martwicę mięśnia sercowego', 'odzwierciedla depolaryzację przedsionków', 'jest zawsze objawem patologicznym w każdym przypadku', 'odzwierciedla repolaryzację komór'], a: 0, rationale: "Poprawnie: fizjologiczny załamek Q (przegrodowy) w odprowadzeniach bocznych (np. I) odzwierciedla prawidłową, wczesną depolaryzację przegrody międzykomorowej, przebiegającą od lewej do prawej strony (kierunek dający ujemne wychylenie widoczne jako Q). Patologiczny (nie fizjologiczny) załamek Q świadczy o martwicy mięśnia sercowego (przebytym zawale) — to odrębne zjawisko od niewielkiego, fizjologicznego Q przegrodowego. Depolaryzacja przedsionków jest odzwierciedlana przez załamek P, nie załamek Q w zespole QRS. Fizjologiczny, niewielki załamek Q przegrodowy NIE jest patologiczny — to normalny wariant zapisu, w przeciwieństwie do szerokiego, głębokiego patologicznego Q. Repolaryzacja komór jest odzwierciedlana przez załamek T, nie przez załamek Q będący częścią depolaryzacji (zespołu QRS)." },
  { targetCategory: 'Wykład 6 — EKG i elektryczna czynność serca', q: 'Gdzie sygnał elektryczny jest przewodzony najwolniej w sercu?', o: ['w łączu przedsionkowo-komorowym (węźle AV)', 'w węźle zatokowo-przedsionkowym (SA)', 'we włóknach Purkinjego', 'w odnogach pęczka Hisa', 'w mięśniu roboczym przedsionków'], a: 0, rationale: "Poprawnie: przewodzenie przez węzeł przedsionkowo-komorowy jest fizjologicznie najwolniejsze w całym układzie przewodzącym serca, co daje niezbędne opóźnienie umożliwiające pełne wypełnienie komór przed ich skurczem. Węzeł zatokowo-przedsionkowy jest miejscem generowania impulsu, z relatywnie szybszym przewodzeniem niż węzeł AV. Włókna Purkinjego przewodzą impuls NAJSZYBCIEJ ze wszystkich struktur układu przewodzącego, umożliwiając niemal jednoczesną aktywację całego mięśnia komór. Odnogi pęczka Hisa przewodzą impuls szybko, znacznie szybciej niż węzeł AV. Mięsień roboczy przedsionków przewodzi impuls szybciej niż węzeł AV, choć wolniej niż wyspecjalizowane włókna przewodzące." },
  { targetCategory: 'Wykład 6 — EKG i elektryczna czynność serca', q: 'Co jest najczęstszą przyczyną wydłużenia czasu depolaryzacji komór (poszerzenia QRS)?', o: ['blok prawej odnogi pęczka Hisa', 'blok przedsionkowo-komorowy I stopnia', 'migotanie przedsionków', 'zespół WPW ze skróconym PQ', 'blok zatokowo-przedsionkowy'], a: 0, rationale: "Poprawnie: blok odnogi pęczka Hisa (np. prawej) opóźnia aktywację jednej z komór, wydłużając czas depolaryzacji komór i poszerzając zespół QRS — jest to jedna z najczęstszych przyczyn tego zjawiska. Blok AV I stopnia dotyczy przewodzenia przedsionek-komora (odstęp PQ), nie bezpośrednio szerokości samego zespołu QRS. Migotanie przedsionków dotyczy zaburzenia rytmu przedsionków, niezwiązanego bezpośrednio z szerokością zespołów QRS (chyba że współistnieje blok odnogi). Zespół WPW skraca odstęp PQ przez drogę dodatkową — choć może dawać falę delta wpływającą na wygląd QRS, klasyczną, najczęstszą przyczyną poszerzenia QRS pozostaje blok odnogi. Blok zatokowo-przedsionkowy dotyczy węzła zatokowego, niezwiązany z szerokością zespołu QRS." },
  { targetCategory: 'Skrypt — Fizjologia układu krążenia', q: 'Dlaczego ściana prawej komory serca jest cieńsza niż ściana lewej komory?', o: ['ponieważ opór w krążeniu płucnym jest mniejszy niż w krążeniu systemowym', 'ponieważ prawa komora przyjmuje mniejszą objętość krwi niż lewa', 'ponieważ prawa komora pracuje z mniejszą częstością niż lewa', 'ponieważ prawa komora generuje wyższe ciśnienie niż lewa', 'ponieważ prawa komora jest unerwiona wyłącznie przywspółczulnie'], a: 0, rationale: "Poprawnie: prawa komora tłoczy krew do krążenia płucnego o niskim oporze naczyniowym, więc wymaga wygenerowania znacznie niższego ciśnienia niż lewa komora pompująca do krążenia systemowego o wysokim oporze — stąd cieńsza ściana mięśniowa. Obie komory w warunkach fizjologicznych przyjmują tę samą objętość krwi (rzuty minutowe są sobie równe), więc różnica objętości nie tłumaczy różnicy grubości ścian. Obie komory pracują z tą samą częstością, więc częstość nie jest przyczyną różnicy grubości. Prawa komora generuje NIŻSZE, a nie wyższe ciśnienie niż lewa — to odwrócenie rzeczywistej zależności ciśnieniowej. Obie komory są unerwione zarówno współczulnie, jak i przywspółczulnie — nie ma różnicy w rodzaju unerwienia tłumaczącej grubość ściany." },
  { targetCategory: 'Wykład 11 — Zaburzenia rytmu serca (arytmie)', q: 'Co jest charakterystyczne dla bloku przedsionkowo-komorowego (AV) I stopnia?', o: ['wydłużenie przewodzenia AV (odstępu PQ) przy zachowanym przewodzeniu każdego pobudzenia', 'całkowity brak przewodzenia AV (dysocjacja przedsionkowo-komorowa)', 'niecałkowite (częściowe) przewodzenie ze zmiennym stosunkiem P do QRS', 'skrócenie odstępu PQ poniżej normy', 'brak jakiegokolwiek wpływu na odstęp PQ'], a: 0, rationale: "Poprawnie: blok AV I stopnia cechuje się stałym wydłużeniem odstępu PQ powyżej 200 ms, przy zachowanym przewodzeniu każdego pobudzenia przedsionkowego do komór. Całkowity brak przewodzenia AV opisuje blok III stopnia (całkowity), znacznie poważniejsze zaburzenie niż blok I stopnia. Niecałkowite przewodzenie ze zmiennym stosunkiem P do QRS opisuje blok AV II stopnia, odrębną, bardziej zaawansowaną jednostkę. Skrócenie PQ jest typowe dla zespołu preekscytacji (WPW), przeciwne do wydłużenia charakterystycznego dla bloku I stopnia. Blok AV I stopnia z definicji istotnie wpływa na odstęp PQ (wydłuża go), więc stwierdzenie o braku wpływu jest nieprawdziwe." },
  { targetCategory: 'Podręcznik patofizjologii — Choroba niedokrwienna serca (IHD) i zawał (MI)', q: 'Co jest najczęstszą przyczyną zatorowości płucnej?', o: ['zakrzepica żył głębokich kończyn dolnych (przemieszczenie skrzepliny)', 'zator tłuszczowy po złamaniach', 'zator powietrzny', 'zator płynem owodniowym', 'pierwotna zakrzepica w tętnicy płucnej'], a: 0, rationale: "Poprawnie: zdecydowana większość zatorów płucnych pochodzi z przemieszczonych skrzeplin powstałych w żyłach głębokich kończyn dolnych (zakrzepica żył głębokich, DVT), będąc najczęstszą przyczyną tej choroby. Zator tłuszczowy po złamaniach jest istotną, ale znacznie rzadszą przyczyną zatorowości płucnej niż DVT. Zator powietrzny jest rzadkim powikłaniem (np. procedur medycznych), znacznie mniej częstym niż zatorowość z DVT. Zator płynem owodniowym jest rzadkim, poważnym powikłaniem położniczym, znacznie rzadszym niż klasyczna zatorowość z DVT. Pierwotna zakrzepica w samej tętnicy płucnej jest rzadkim zjawiskiem — typowo materiał zatorowy pochodzi z odległego miejsca (żyły kończyn dolnych), nie powstaje pierwotnie w tętnicy płucnej." },
  { targetCategory: 'Skrypt — Fizjologia nerek', q: 'Z jakim hormonem związana jest neurofizyna II?', o: ['wazopresyną (AVP)', 'oksytocyną', 'insuliną', 'kortyzolem', 'aldosteronem'], a: 0, rationale: "Poprawnie: neurofizyna II jest białkiem nośnikowym towarzyszącym wazopresynie (AVP) podczas jej transportu aksonalnego z podwzgórza do tylnego płata przysadki. Neurofizyna I (nie II) jest białkiem nośnikowym towarzyszącym oksytocynie — to odrębne białko od neurofizyny II. Insulina jest hormonem peptydowym trzustki, transportowanym w odrębny sposób, niezwiązanym z neurofizynami. Kortyzol jest hormonem steroidowym, transportowanym we krwi przez transkortynę (CBG), niezwiązanym z neurofizynami (białkami nośnikowymi neurohormonów peptydowych). Aldosteron jest hormonem steroidowym kory nadnerczy, niezwiązanym z systemem neurofizyn." },
  { targetCategory: 'Podręcznik patofizjologii — Przysadka i tarczyca', q: 'Do czego jest potrzebny enzym tyreoperoksydaza (TPO)?', o: ['utleniania jonów jodkowych i jodowania reszt tyrozynowych tyreoglobuliny', 'transportu jodu do komórki pęcherzykowej tarczycy', 'magazynowania hormonów tarczycy w koloidzie', 'transportu hormonów tarczycy we krwi', 'rozkładu nadmiaru hormonów tarczycy w wątrobie'], a: 0, rationale: "Poprawnie: tyreoperoksydaza katalizuje utlenianie jonów jodkowych oraz jodowanie reszt tyrozynowych tyreoglobuliny, a także sprzęganie jodotyrozyn w hormony tarczycy — kluczowy enzym syntezy T3/T4. Transport jodu do komórki pęcherzykowej jest funkcją symportera sodowo-jodkowego (NIS), odrębnego białka od tyreoperoksydazy. Magazynowanie hormonów w koloidzie zachodzi w postaci związanej z tyreoglobuliną, ale to nie jest bezpośrednia funkcja samej tyreoperoksydazy (enzymu katalizującego syntezę, nie magazynowanie). Transport hormonów tarczycy we krwi jest funkcją białek wiążących (np. TBG), niezwiązanych z tyreoperoksydazą. Rozkład nadmiaru hormonów tarczycy zachodzi w wątrobie przy udziale innych enzymów (dejodynaz), niezwiązanych z tyreoperoksydazą działającą w samej tarczycy." },
  { targetCategory: 'Podręcznik patofizjologii — Gorączka', q: 'Które zdanie o hipertermii złośliwej jest prawdziwe?', o: ['może wystąpić po podaniu znieczulenia ogólnego (anestetyki wziewne, suksametonium)', 'jest zawsze spowodowana infekcją bakteryjną', 'jest łagodnym, niegroźnym stanem niewymagającym leczenia', 'nie ma podłoża genetycznego', 'występuje wyłącznie u dzieci, nigdy u dorosłych'], a: 0, rationale: "Poprawnie: hipertermia złośliwa jest rzadką, genetycznie uwarunkowaną reakcją na anestetyki wziewne lub suksametonium podczas znieczulenia ogólnego, prowadzącą do niekontrolowanego wzrostu metabolizmu mięśniowego i temperatury ciała. Nie jest ona wywołana infekcją bakteryjną — jej mechanizm jest farmakogenetyczny, związany z nieprawidłową funkcją receptora rianodynowego w mięśniach. Hipertermia złośliwa jest stanem POTENCJALNIE ŚMIERTELNYM, wymagającym natychmiastowego leczenia (dantrolen), nie łagodnym, niegroźnym stanem. Hipertermia złośliwa ma UDOKUMENTOWANE podłoże genetyczne (mutacje genu RYR1), więc stwierdzenie o jego braku jest nieprawdziwe. Hipertermia złośliwa może wystąpić zarówno u dzieci, jak i dorosłych poddawanych znieczuleniu ogólnemu z użyciem odpowiednich czynników wyzwalających." },
  { targetCategory: 'Skrypt — Neurofizjologia I', q: 'Które zdanie o drodze piramidowej (korowo-rdzeniowej) jest fałszywe?', o: ['droga piramidowa krzyżuje się wyłącznie na poziomie rdzenia kręgowego, nigdy w rdzeniu przedłużonym', 'większość włókien drogi piramidowej krzyżuje się w piramidach rdzenia przedłużonego', 'droga piramidowa odpowiada za ruchy dowolne', 'uszkodzenie drogi piramidowej powyżej skrzyżowania daje objawy po stronie przeciwnej', 'droga piramidowa boczna unerwia głównie dystalne mięśnie kończyn'], a: 0, rationale: "Poprawnie (zdanie fałszywe): większość (ok. 85-90%) włókien drogi piramidowej krzyżuje się WŁAŚNIE na poziomie piramid RDZENIA PRZEDŁUŻONEGO (tworząc drogę korowo-rdzeniową boczną), a nie wyłącznie na poziomie rdzenia kręgowego — to błędne, fałszywe stwierdzenie o wyłącznym miejscu skrzyżowania. Stwierdzenie, że większość włókien krzyżuje się w piramidach rdzenia przedłużonego, jest prawdziwym, dokładnym opisem anatomii tej drogi. Droga piramidowa faktycznie odpowiada za inicjację i kontrolę ruchów dowolnych — to jej podstawowa, prawdziwa funkcja. Uszkodzenie drogi piramidowej powyżej miejsca skrzyżowania (np. w mózgu) faktycznie daje objawy po stronie PRZECIWNEJ (kontralateralnej) do uszkodzenia — prawdziwe stwierdzenie zgodne z krzyżowaniem się włókien. Droga korowo-rdzeniowa boczna faktycznie unerwia głównie dystalne mięśnie kończyn, odpowiedzialne za precyzyjne ruchy — prawdziwe stwierdzenie." },
  { targetCategory: 'Podręcznik patofizjologii — Przytarczyce i wapń', q: 'Co się dzieje w organizmie przy niedoborze witaminy D?', o: ['hipokalcemia, hipofosfatemia i zwiększone stężenie parathormonu (wtórna nadczynność przytarczyc)', 'hiperkalcemia, hiperfosfatemia i zmniejszone stężenie parathormonu', 'hipokalcemia, hiperfosfatemia i zmniejszone stężenie parathormonu', 'prawidłowe stężenia wapnia, fosforanów i parathormonu', 'hiperkalcemia i zahamowanie wydzielania parathormonu'], a: 0, rationale: "Poprawnie: niedobór witaminy D upośledza wchłanianie wapnia i fosforanów w jelitach, dając hipokalcemię i hipofosfatemię, na co przytarczyce odpowiadają kompensacyjnym zwiększeniem wydzielania parathormonu (wtórna nadczynność przytarczyc), próbując zmobilizować wapń z kości. Hiperkalcemia i hiperfosfatemia są sprzeczne z mechanizmem niedoboru witaminy D, który upośledza, a nie nasila wchłanianie tych jonów. Hipokalcemia jest prawidłowym elementem tego zaburzenia, ale fosforany są typowo OBNIŻONE (nie podwyższone), a PTH jest ZWIĘKSZONY (nie zmniejszony) jako odpowiedź kompensacyjna. Niedobór witaminy D wywołuje istotne, wyraźne zaburzenia gospodarki wapniowo-fosforanowej, więc stwierdzenie o prawidłowych wartościach jest nieprawdziwe. Niedobór witaminy D daje hipokalcemię (nie hiperkalcemię) i ZWIĘKSZONE (nie zahamowane) wydzielanie PTH jako mechanizm kompensacyjny." },
  { targetCategory: 'Skrypt — Fizjologia oddychania (zaawansowana)', q: 'Które zdanie o podatności (compliance) płuc jest prawdziwe?', o: ['gdy podatność płuc jest mniejsza, mięśnie oddechowe wykonują większą pracę, a wraz z wiekiem podatność płuc rośnie', 'mniejsza podatność płuc zmniejsza pracę mięśni oddechowych', 'podatność płuc maleje wraz z wiekiem', 'podatność płuc nie ma związku z pracą oddychania', 'podatność płuc jest stała przez całe życie, niezależnie od wieku'], a: 0, rationale: "Poprawnie: mniejsza podatność (sztywniejsze płuca) wymaga większej pracy mięśni oddechowych do ich rozciągnięcia podczas wdechu, a wraz z wiekiem (z powodu zmian strukturalnych tkanki płucnej i utraty elastycznych włókien) podatność płuc fizjologicznie ROŚNIE (mimo utraty sprężystości sprzyjającej też rozedmie starczej). Twierdzenie, że mniejsza podatność zmniejsza pracę mięśni, jest odwróceniem rzeczywistej zależności — sztywniejsze płuca wymagają WIĘKSZEGO wysiłku do rozciągnięcia. Podatność płuc u zdrowych osób starszych fizjologicznie ROŚNIE (nie maleje) z powodu stopniowej utraty elastycznych włókien tkanki płucnej. Podatność płuc ma bezpośredni, istotny związek z pracą oddychania — im mniejsza podatność, tym większa praca potrzebna do wdechu. Podatność płuc zmienia się z wiekiem (fizjologicznie rośnie), więc stwierdzenie o jej stałości przez całe życie jest nieprawdziwe." },
  { targetCategory: 'Skrypt — Fizjologia układu krążenia', q: 'Jaki rodzaj tropizmu (właściwości mięśnia sercowego) odnosi się do siły skurczu serca?', o: ['inotropizm', 'chronotropizm', 'dromotropizm', 'batmotropizm', 'lusitropizm wyłącznie w znaczeniu częstości'], a: 0, rationale: "Poprawnie: inotropizm odnosi się do siły skurczu mięśnia sercowego — działanie inotropowo dodatnie zwiększa, a ujemne zmniejsza tę siłę. Chronotropizm dotyczy częstości akcji serca, nie siły skurczu. Dromotropizm dotyczy szybkości przewodzenia impulsu przez układ przewodzący serca, nie siły skurczu. Batmotropizm dotyczy progu pobudliwości komórek mięśnia sercowego, nie bezpośrednio siły skurczu. Lusitropizm dotyczy zdolności do rozkurczu (relaksacji) mięśnia sercowego, odrębnej właściwości od siły skurczu, i nie jest definiowany w kategoriach częstości." },
];

